import java.lang.reflect.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        Sapa asli = nama -> "Halo " + nama;
        Sapa keras = (Sapa) Proxy.newProxyInstance(Sapa.class.getClassLoader(), new Class<?>[] {Sapa.class},
                (proxy, method, arg) -> ((String) method.invoke(asli, arg)).toUpperCase());
        System.out.println(asli.sapa("Sari"));
        System.out.println(keras.sapa("Sari"));
    }
}

interface Sapa {
    String sapa(String nama);
}

