interface LayananTodo {
    String tambah(String judul);

    int jumlah();
}

class LayananTodoAsli implements LayananTodo {
    private final List<String> data = new ArrayList<>();

    public String tambah(String judul) {
        data.add(judul);
        return "Tersimpan: " + judul;
    }

    public int jumlah() {
        return data.size();
    }
}

class Pencatat implements InvocationHandler {
    private final Object asli;

    Pencatat(Object asli) {
        this.asli = asli;
    }

    @Override
    public Object invoke(Object proxy, Method method, Object[] args) throws Throwable {
        System.out.println("[log] memanggil " + method.getName() + (args == null ? "" : Arrays.toString(args)));
        Object hasil = method.invoke(asli, args);
        System.out.println("[log] selesai " + method.getName() + " -> " + hasil);
        return hasil;
    }
}

