public class Main {
    public static void main(String[] args) throws Exception {
        PenghitungPanggilan penghitung = new PenghitungPanggilan(new LayananTodoAsli());
        LayananTodo layanan = (LayananTodo) Proxy.newProxyInstance(
                LayananTodo.class.getClassLoader(), new Class<?>[] {LayananTodo.class}, penghitung);
