class PenghitungPanggilan implements InvocationHandler {
    final Object asli;
    final Map<String, Integer> jumlah = new TreeMap<>();

    PenghitungPanggilan(Object asli) {
        this.asli = asli;
    }

    @Override
    public Object invoke(Object proxy, Method method, Object[] args) throws Throwable {
        jumlah.merge(method.getName(), 1, Integer::sum);
        return method.invoke(asli, args);
    }
}
